package io.lumine.mythic.lib.api.crafting.recipes;
import io.lumine.mythic.lib.api.crafting.ingredients.*; import io.lumine.mythic.lib.api.crafting.uimanager.ProvidedUIFilter; import io.lumine.mythic.lib.api.util.Ref; import net.minecraft.item.ItemStack; import java.util.*;
public class ShapedRecipe extends MythicRecipe implements VanillaBookableRecipe { private int width,height; public ShapedRecipe(String n,ArrayList<ShapedIngredient> i){super(n,new ArrayList<>(i));recalculateSize();} public ShapedRecipe(String n,ShapedIngredient... i){this(n,new ArrayList<>(Arrays.asList(i)));} public static ShapedRecipe single(String name,ProvidedUIFilter... filters){ArrayList<ShapedIngredient> list=new ArrayList<>();for(int i=0;i<filters.length;i++)list.add(new ShapedIngredient(filters[i],0,i));return new ShapedRecipe(name,list);} public static ShapedRecipe unsharpen(ShapedRecipe r){return new ShapedRecipe(r.getName(),r.ingredients.stream().map(i->((ShapedIngredient)i).clone()).toArray(ShapedIngredient[]::new));} public MythicRecipeStation getType(){return MythicRecipeStation.WORKBENCH;} public void clearIngredients(){super.clearIngredients();width=height=0;} public void addIngredient(MythicRecipeIngredient i){if(!(i instanceof ShapedIngredient))throw new IllegalArgumentException("ShapedIngredient required");ingredients.add(i);recalculateSize();} public void recalculateSize(){width=height=0;for(MythicRecipeIngredient raw:ingredients){ShapedIngredient i=(ShapedIngredient)raw;width=Math.max(width,i.getHorizontalOffset()+1);height=Math.max(height,i.getVerticalOffset()+1);}} public ShapedIngredient getIngredientAt(int x,int y){for(MythicRecipeIngredient raw:ingredients){ShapedIngredient i=(ShapedIngredient)raw;if(i.getHorizontalOffset()==x&&i.getVerticalOffset()==y)return i;}return null;} public int getWidth(){return width;} public int getHeight(){return height;} public ArrayList<ArrayList<ShapedIngredient>> permute(int maxW,int maxH){ArrayList<ArrayList<ShapedIngredient>> out=new ArrayList<>();for(int oy=0;oy<=maxH-height;oy++)for(int ox=0;ox<=maxW-width;ox++){ArrayList<ShapedIngredient> p=new ArrayList<>();for(MythicRecipeIngredient raw:ingredients)p.add(((ShapedIngredient)raw).adapt(oy,ox));out.add(p);}return out;} public MythicRecipeInventory matches(MythicRecipeInventory inv,Ref<Integer> amount){int iw=inv.getWidth(),ih=inv.getHeight();for(int oy=0;oy<=ih-height;oy++)for(int ox=0;ox<=iw-width;ox++){boolean ok=true;int crafts=Integer.MAX_VALUE;for(int y=0;y<ih&&ok;y++)for(int x=0;x<iw;x++){ShapedIngredient expected=(x>=ox&&y>=oy&&x<ox+width&&y<oy+height)?getIngredientAt(x-ox,y-oy):null;ItemStack stack=inv.getItemAt(x,y);if(expected==null){if(stack!=null&&!stack.isEmpty()){ok=false;break;}}else if(!expected.getIngredient().matches(stack,null)){ok=false;break;}else crafts=Math.min(crafts,Math.max(1,stack.getCount()));}if(ok){if(amount!=null)amount.set(crafts==Integer.MAX_VALUE?1:crafts);return inv.clone();}}return null;} }
